fn format_raw_stdout(raw: &Mutex<Vec<u8>>) -> String {
    static TIMESTAMP_MATCHER: Lazy<Regex> = Lazy::new(|| Regex::new(r"<\d+>").unwrap());
    let stdout = raw.lock().unwrap();
    TIMESTAMP_MATCHER
        .replace_all(std::str::from_utf8(&stdout).unwrap(), "<TIMESTAMP_REMOVED>")
        .into()
}

